import * as exec from '@actions/exec';
import * as mexec from './exec.js';
export const defaults = {
    targetBranch: 'gh-pages',
    committer: 'GitHub <noreply@github.com>',
    author: 'github-actions[bot] <41898282+github-actions[bot]@users.noreply.github.com>',
    message: 'Deploy to GitHub pages'
};
export async function remoteBranchExists(remoteURL, branch) {
    return await mexec.exec('git', ['ls-remote', '--heads', remoteURL, branch], true).then(res => {
        if (res.stderr != '' && !res.success) {
            throw new Error(res.stderr);
        }
        return res.stdout.trim().length > 0;
    });
}
export async function clone(remoteURL, branch, dest) {
    await exec.exec('git', ['clone', '--quiet', '--branch', branch, '--depth', '1', remoteURL, dest]);
}
export async function init(dest) {
    await exec.exec('git', ['init', dest]);
}
export async function checkout(branch) {
    await exec.exec('git', ['checkout', '--orphan', branch]);
}
export async function isDirty() {
    return await mexec.exec('git', ['status', '--short'], true).then(res => {
        if (res.stderr != '' && !res.success) {
            throw new Error(res.stderr);
        }
        return res.stdout.trim().length > 0;
    });
}
export async function hasChanges() {
    return await mexec.exec('git', ['status', '--porcelain'], true).then(res => {
        if (res.stderr != '' && !res.success) {
            throw new Error(res.stderr);
        }
        return res.stdout.trim().length > 0;
    });
}
export async function setConfig(key, value) {
    await exec.exec('git', ['config', key, value]);
}
export async function add(pattern, verbose) {
    const args = ['add'];
    if (verbose) {
        args.push('--verbose');
    }
    args.push('--all', pattern);
    await exec.exec('git', args);
}
export async function commit(allowEmptyCommit, author, message) {
    const args = [];
    args.push('commit');
    if (allowEmptyCommit) {
        args.push('--allow-empty');
    }
    if (author !== '') {
        args.push('--author', author);
    }
    args.push('--message', message);
    await exec.exec('git', args);
}
export async function showStat() {
    return await mexec.exec('git', ['show', `--stat-count=1000`, 'HEAD'], true).then(res => {
        if (res.stderr != '' && !res.success) {
            throw new Error(res.stderr);
        }
        return res.stdout.trim();
    });
}
export async function push(remoteURL, branch, force) {
    const args = [];
    args.push('push');
    if (force) {
        args.push('--force');
    }
    args.push(remoteURL, branch);
    await exec.exec('git', args);
}
